import './App.css';
import Modal from './Components/modal.js'

import { useEffect, useState } from 'react'

import { auth, app, db } from './firebase.js';
import { signInWithPopup, GoogleAuthProvider, onAuthStateChanged, signOut } from 'firebase/auth';
import { doc, collection, setDoc, getDoc, addDoc, updateDoc, arrayUnion, arrayRemove } from 'firebase/firestore';

import { useAuthState } from 'react-firebase-hooks/auth';


function App() {
  const [user] = useAuthState(auth);

  const [changedPuzzleList, setChangedPuzzleList] = useState(0);
  const [puzzleList, setPuzzleList] = useState([]);

  const [modal, setModal] = useState(false);
  let modalPurpose = "";
  const toggleModal = (event) => {
    setModal(!modal);
    console.log(event.target.id);
  };


  useEffect(() => {
    const fetchData = async () => {
      try {
        const userRef = doc(db, 'users', user.uid);
        const userSnap = await getDoc(userRef);
        console.log(userSnap.data().puzzles);
        setPuzzleList(userSnap.data().puzzles);
      } catch(error) {
        console.log(error);
      }
      }

  fetchData();
  },[changedPuzzleList, user]);

  return (
    <div className="App">
        <header>
          Hi
          {user ? <>
          <AddPuzzleButton
           user={user}
           changedPuzzleList={changedPuzzleList}
           setChangedPuzzleList={setChangedPuzzleList} />
          <SignOutButton /> 
           </>
           : <SignInButton />}


          <button onClick={toggleModal} className="btn-modal" id='11'>Add Puzzle</button>
          <Modal modal={modal} toggleModal={toggleModal}/>
        </header>

        <div>
          {user ? 
          <>
           <PuzzlesBoard
           puzzleList={puzzleList}
           user={user}
           changedPuzzleList={changedPuzzleList}
           setChangedPuzzleList={setChangedPuzzleList} /> 
           </>
           : null }


        </div>
    </div>
  );
}

function SignInButton() {
  const SignIn = () => {
    const provider = new GoogleAuthProvider();
    signInWithPopup(auth, provider)
    .then(async (result) => {
      let user = result.user
      const userRef = doc(db, 'users', user.uid);
      const userSnap = await getDoc(userRef);
      if(!userSnap.exists()) {
        console.log(user);
        await setDoc(doc(db, 'users', user.uid), {
          email: user.email,
          name: user.displayName,
          puzzles: []
        });
      }
    });
  }

  return (
    <button onClick={SignIn}>Sign In</button>
  )
}

function SignOutButton() {
  const SignOut = () => {
    signOut(auth);
  }
  return auth.currentUser && (
    <button onClick={SignOut}>Sign Out</button>
  )
}

function AddPuzzleButton(props) {

  const [formPuzzleTitle, setFormPuzzleTitle] = useState('');
  const AddPuzzle = async (e) => {
    e.preventDefault();
    const userRef = doc(db, 'users', props.user.uid);
    await updateDoc(userRef, {
      puzzles:  arrayUnion(formPuzzleTitle)
    })

    setFormPuzzleTitle('');
    props.setChangedPuzzleList(props.changedPuzzleList+1);
  }

  return (
    <form onSubmit={AddPuzzle}>
      <input value={formPuzzleTitle} onChange={(e) => setFormPuzzleTitle(e.target.value)} placeholder='Puzzle Title'/>
      <button type='submit' disabled={!formPuzzleTitle}>Add Puzzle</button>
    </form>
  )
}

 function PuzzlesBoard(props) {

  /*const [puzzleList, setPuzzleList] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
        const userRef = doc(db, 'users', props.user.uid);
        const userSnap = await getDoc(userRef);
        setPuzzleList(userSnap.data().puzzles);
        console.log(userSnap.data().puzzles);
        console.log(puzzleList);
      }

  fetchData();
  },[props.addedPuzzleFlag]);*/


  if(props.puzzleList) return (
    <div className='puzzleBoard'>
      {props.puzzleList.map(puzzle => <PuzzleCard puzzle={puzzle} user={props.user} 
      changedPuzzleList={props.changedPuzzleList}
       setChangedPuzzleList={props.setChangedPuzzleList}/>)}
    </div>
  )
}

function PuzzleCard(props) {

  const DeletePuzzle = async () => {
    const userRef = doc(db, 'users', props.user.uid);
    await updateDoc(userRef, {
      puzzles: arrayRemove(props.puzzle)
    });
    props.setChangedPuzzleList(props.changedPuzzleList+1);
  }
  return (
    <div className='puzzleCard'>
      <p>{props.puzzle}</p>
      <button onClick={DeletePuzzle}>Delete</button>
    </div>
  )
}

export default App;
